import{_ as a,c as s,o,ah as n,ao as i,ap as l}from"./chunks/framework.Dq2_gudl.js";const b=JSON.parse('{"title":"¿Volveré a ver a mi mascota? Lo que la Biblia dice sobre los animales y el cielo","description":"La pregunta más profunda tras perder a una mascota: ¿estará en el cielo? Qué nos ofrecen Romanos, Isaías y Apocalipsis.","frontmatter":{"title":"¿Volveré a ver a mi mascota? Lo que la Biblia dice sobre los animales y el cielo","description":"La pregunta más profunda tras perder a una mascota: ¿estará en el cielo? Qué nos ofrecen Romanos, Isaías y Apocalipsis."},"headers":[],"relativePath":"es/pets-in-heaven/will-i-see-my-pet-again.md","filePath":"es/pets-in-heaven/will-i-see-my-pet-again.md"}'),r={name:"es/pets-in-heaven/will-i-see-my-pet-again.md"};function t(c,e,p,u,d,m){return o(),s("div",null,[...e[0]||(e[0]=[n('<div class="pl-quote"><p>«Sé que yo estaré en el cielo. Solo quiero saber si él estará allí esperándome.»</p><p class="pl-quote-soft">Es la pregunta que más hacen quienes pierden a un compañero animal, y la que más cuesta decir en voz alta.</p></div><section class="pl-section"><h2>Una palabra honesta primero</h2><p>La Biblia nunca dice, en un solo versículo, que «cada mascota se reunirá con su dueño en el cielo». Quien lo afirma con esa seguridad ha ido más allá de lo que dicen las Escrituras.</p><p>Pero no te desesperes por eso. El cuadro que pinta la Biblia es mucho más amplio de lo que suponemos: la redención de Dios nunca fue solo «sacar algunas almas humanas de los escombros»: es <strong>la renovación de toda la creación</strong>. Y los animales están en ese cuadro de principio a fin.</p></section><section class="pl-section"><h2>1. La creación misma espera con nosotros</h2><blockquote><p><strong>Romanos 8:19-22</strong></p><p>&quot;For the earnest expectation of the creature waiteth for the manifestation of the sons of God… For we know that the whole creation groaneth and travaileth in pain together until now.&quot;</p></blockquote><p>Pablo dice algo asombroso aquí: no solo las personas gimen y esperan. <em>La creación misma</em> gime y espera la redención. Los animales no son el decorado que quedó fuera de la salvación: miran hacia el mismo final que nosotros.</p><p>Cuando dices «era tan bueno, no debería simplemente desaparecer», lo que sientes es exactamente lo que siente la creación. La Escritura dice que ese dolor tendrá respuesta.</p></section><section class="pl-section"><h2>2. El mundo que Dios hará tiene animales</h2><blockquote><p><strong>Isaías 11:6-9</strong></p><p>&quot;The wolf also shall dwell with the lamb, and the leopard shall lie down with the kid; and the calf and the young lion and the fatling together; and a little child shall lead them.&quot;</p></blockquote><p>El futuro que vio Isaías no es un mundo solo de luz y nubes. Vio lobos, corderos, leopardos, cabritos, becerros y leones: un mundo donde nada hiere y todos se acuestan seguros.</p><p>Si la intención de Dios con los animales fuera «son solo para esta vida y luego se acabó», no les habría dado un lugar en Sus promesas. Se lo dio.</p><p>Y al describir el nuevo cielo y la nueva tierra, Apocalipsis dice:</p><blockquote><p><strong>Apocalipsis 21:4-5</strong></p><p>&quot;And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away. …Behold, I make all things new.&quot;</p></blockquote><p>«Ya no habrá muerte» es un anuncio sobre toda la creación. La muerte que atravesó tu mascota es una de las cosas que será abolida.</p></section><section class="pl-section"><h2>3. ¿Hasta dónde podemos esperar?</h2><p>Podemos esperar, porque Dios no abandona lo que creó. Podemos esperar, porque la resurrección de Cristo son las primicias de una nueva creación, y la Escritura dice que su alcance es «todas las cosas». Podemos esperar, porque el Dios que creó a los animales y se deleitó en ellos no dejará de repente de preocuparse por ellos.</p><p>En cuanto a «¿será el mismo?» y «¿se acordará de mí?»: la Biblia no da detalles. Nos da un Dios digno de confianza, y los detalles están en Sus manos. Ese silencio no es para torturarnos; es una invitación a poner lo que no sabemos en manos buenas.</p><p class="pl-quote-soft">Si quieres, puedes orar así:</p></section><div class="pl-quote"><p>«Señor, no conozco los detalles del cielo, pero creo que Tú eres bueno.<br>Tú lo creaste. Tú cuidaste cada día de su vida. Tú ves mis lágrimas ahora.<br>Lo pongo en Tus manos, como me pongo yo en Tus manos.<br>Si hay un lugar para él en Tus promesas, gracias.<br>Y si alguien debe cuidarlo ahora, me alegra que seas Tú. Amén.»</p></div><section class="pl-section"><h2>Para un día especialmente difícil</h2><p>El salmista escribió: «oh Señor, tú preservas a los hombres y a las bestias» (Salmos 36:6). Es una línea corta, pero es uno de los pocos versículos que colocan a los animales directamente dentro del cuidado preservador de Dios.</p><p>Tu mascota pertenece al Dios que preserva «a los hombres y a las bestias». Lo que quizá necesites hoy no es una respuesta completa, sino solo esto: está en las manos de Dios, y Dios es bueno.</p><p><a href="/es/pets-in-heaven/">← Volver a Pets in Heaven</a> ｜ Siguiente: <a href="/es/pets-in-heaven/not-one-sparrow-forgotten">Ni un gorrión es olvidado</a></p></section><div class="pl-cta"><h2>Escribe su nombre.</h2><p>Escribe su nombre, su lugar favorito, la frase que nunca dijiste. PetLoss es un espacio privado — sin subidas, sin prisa — que te ayuda a ordenarlo despacio.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">Descargar en el App Store</a></div><div class="pl-bible"><h3>Deja que la Palabra te siga acompañando</h3><p>Todos los versículos de este artículo provienen de la Biblia. Con Rainbow Bible puedes leer las Escrituras en cualquier momento y poner un widget con el versículo del día: una pequeña luz en los días en que lo echas de menos.</p><div class="pl-bible-shots"><figure><img src="'+i+'" alt="Widget de Rainbow Bible mostrando 2 Timoteo 2:13" loading="lazy"><figcaption>Versículo del día en tu pantalla</figcaption></figure><figure><img src="'+l+'" alt="Rainbow Bible — tema Mascotas en el cielo mostrando Mateo 10:29-31" loading="lazy"><figcaption>Lee las Escrituras en Mascotas en el cielo</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">Descargar Rainbow Bible en el App Store</a></div>',9)])])}const g=a(r,[["render",t]]);export{b as __pageData,g as default};
